ALTER TABLE commission_rules ADD COLUMN kind text NOT NULL DEFAULT 'percentage' CHECK(kind IN ('percentage','fixed'));
ALTER TABLE commission_rules ADD COLUMN fixed_amount_in_cents integer CHECK(fixed_amount_in_cents >= 0);
ALTER TABLE commission_rules ADD COLUMN service_id uuid REFERENCES services(id);
ALTER TABLE commission_rules ADD COLUMN effective_until date;
ALTER TABLE commission_rules ADD CONSTRAINT commission_rule_fixed CHECK(kind <> 'fixed' OR fixed_amount_in_cents IS NOT NULL);
ALTER TABLE commission_rules ADD CONSTRAINT commission_rule_period CHECK(effective_until IS NULL OR effective_until >= effective_from);
ALTER TABLE commission_rules DROP CONSTRAINT commission_rules_clinic_id_professional_id_effective_from_key;
DROP INDEX commission_rules_user_effective_idx;
CREATE UNIQUE INDEX commission_rules_professional_scope_idx ON commission_rules(clinic_id,professional_id,effective_from,coalesce(service_id,'00000000-0000-0000-0000-000000000000'::uuid)) WHERE professional_id IS NOT NULL;
CREATE UNIQUE INDEX commission_rules_user_scope_idx ON commission_rules(clinic_id,user_id,effective_from,coalesce(service_id,'00000000-0000-0000-0000-000000000000'::uuid)) WHERE user_id IS NOT NULL;
ALTER TABLE commission_entries ALTER COLUMN appointment_id DROP NOT NULL;
ALTER TABLE commission_entries ADD COLUMN group_attendance_id uuid REFERENCES group_attendance(id);
ALTER TABLE commission_entries ADD COLUMN service_id uuid REFERENCES services(id);
ALTER TABLE commission_entries ADD COLUMN rule_snapshot jsonb;
ALTER TABLE commission_entries ADD CONSTRAINT commission_entry_source CHECK((appointment_id IS NULL) <> (group_attendance_id IS NULL));
CREATE UNIQUE INDEX commission_entries_attendance_idx ON commission_entries(clinic_id,group_attendance_id) WHERE group_attendance_id IS NOT NULL;
ALTER TABLE payables ADD COLUMN commission_id uuid REFERENCES commission_entries(id);
CREATE UNIQUE INDEX payables_commission_idx ON payables(clinic_id,commission_id) WHERE commission_id IS NOT NULL AND status <> 'cancelled';
